def _generate_logo_png_bytes(accent_hex, text="Camlytix®"):
    w, h = 360, 96
    img = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    accent = tuple(int(accent_hex.lstrip(
        "#")[i:i + 2], 16) for i in (0, 2, 4)) + (255,)

    # Simple camera-eye glyph
    draw.ellipse([6, 18, 66, 78], outline=accent, width=4)
    draw.ellipse([26, 38, 46, 58], fill=accent)

    try:
        from PIL import ImageFont
        font = ImageFont.load_default()
    except Exception:
        font = None
    draw.text((80, 36), text, fill=accent, font=font)

    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()


