LOGO_DARK_BYTES = base64.b64decode(
    ""
)

# Light-theme variant of the logo (white/black-text version) — used when
# the app is switched to light mode so the wordmark stays readable
# against the light header background.
LOGO_LIGHT_BYTES = base64.b64decode(
    ""
)


LOGOS = {"dark": LOGO_DARK_BYTES, "light": LOGO_LIGHT_BYTES}


def _compose_logo_image(theme, bg_hex, height=76):
    raw = LOGOS.get(theme, LOGO_DARK_BYTES)
    logo_img = Image.open(io.BytesIO(raw)).convert("RGBA")
    lw = int(logo_img.width * height / logo_img.height)
    logo_img = logo_img.resize((lw, height), Image.LANCZOS)
    bg_col = tuple(int(bg_hex.lstrip("#")[i:i+2], 16) for i in (0, 2, 4))
    bg_img = Image.new("RGBA", logo_img.size, bg_col + (255,))
    bg_img.paste(logo_img, mask=logo_img.split()[3])
    return bg_img.convert("RGB")


