def get_db_path():
    if getattr(sys, "frozen", False):
        base_dir = os.path.dirname(sys.executable)
    else:
        base_dir = os.path.dirname(os.path.abspath(__file__))

    # Primary DB file name used by this app.
    primary = os.path.join(base_dir, "camlytixvms.db")
    if os.path.exists(primary):
        return primary

    legacy = os.path.join(base_dir, "vms.db")
    if os.path.exists(legacy):
        return legacy

    # Neither exists yet (first run) — create the primary file.
    return primary


def get_app_data_dir():
    """Cross-platform folder for screenshots/recordings, placed next to
    the script (or the frozen executable) instead of assuming a
    Windows-only `D:\\CameraData` path exists."""
    if getattr(sys, "frozen", False):
        base_dir = os.path.dirname(sys.executable)
    else:
        base_dir = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_dir, "CameraData")


DB_FILE = get_db_path()


def _log_crash(context, exc=None):
    try:
        os.makedirs(get_app_data_dir(), exist_ok=True)
        log_path = os.path.join(get_app_data_dir(), "crash.log")
        with open(log_path, "a", encoding="utf-8") as f:
            f.write(f"\n[{datetime.datetime.now()}] {context}\n")
            f.write(traceback.format_exc() if exc is None else str(exc))
            f.write("\n")
    except Exception:
        pass

