# ─────────────────────────────────────────────
#  Plaintext-vs-encrypted detection + one-time migration
# ─────────────────────────────────────────────
def _is_plaintext_sqlite(path):
   
    if not os.path.exists(path):
        return False
    try:
        conn = sqlite3.connect(path)
        conn.execute("SELECT name FROM sqlite_master LIMIT 1;")
        conn.close()
        return True
    except Exception:
        return False


def _encrypt_plaintext_db(path, password):
    tmp_encrypted = path + ".encrypting.tmp"
    if os.path.exists(tmp_encrypted):
        os.remove(tmp_encrypted)

    conn = sqlcipher.connect(path)   # SQLCipher can open plaintext files fine
    try:
        conn.execute(
            f"ATTACH DATABASE '{tmp_encrypted}' AS encrypted KEY '{password}';")
        conn.execute("SELECT sqlcipher_export('encrypted');")
        conn.execute("DETACH DATABASE encrypted;")
    finally:
        conn.close()

    backup_path = path + ".plaintext.bak"
    if os.path.exists(backup_path):
        os.remove(backup_path)
    os.rename(path, backup_path)
    os.rename(tmp_encrypted, path)


def _ensure_encrypted(path=None, password=None):
    path = path or DB_FILE
    password = password or DB_PASSWORD

    if not os.path.exists(path):
        return

    if _is_plaintext_sqlite(path):
        _encrypt_plaintext_db(path, password)


def _connect():
    conn = sqlcipher.connect(DB_FILE)
    conn.execute(f"PRAGMA key='{DB_PASSWORD}';")
    conn.row_factory = sqlcipher.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db():
    # Must run BEFORE the first _connect() call, so an old plaintext
    # file gets encrypted instead of _connect() failing to read it.
    _ensure_encrypted()

    conn = _connect()
    try:
        # groups table must exist before devices references it
        conn.execute("""
            CREATE TABLE IF NOT EXISTS groups (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                name    TEXT  NULL UNIQUE,
                display_order INTEGER NULL DEFAULT 0
            )
        """)

        conn.execute("""
            CREATE TABLE IF NOT EXISTS manufacturers (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                name    TEXT  NULL UNIQUE,
                streaming_url TEXT NULL DEFAULT '',
                display_order INTEGER NULL DEFAULT 0
            )
        """)

        conn.execute("""
            CREATE TABLE IF NOT EXISTS devices (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                name            TEXT NOT NULL DEFAULT 'Camera',
                ip              TEXT NOT NULL DEFAULT '',
                channel_no      INTEGER NOT NULL DEFAULT 1,
                port            INTEGER NOT NULL DEFAULT 37777,
                username        TEXT NOT NULL DEFAULT 'admin',
                password        TEXT NOT NULL DEFAULT '',
                device_type     TEXT NOT NULL DEFAULT 'IP Camera',
                model           TEXT NOT NULL DEFAULT '',
                manufacturer    TEXT NOT NULL DEFAULT 'CP Plus',
                location        TEXT NOT NULL DEFAULT '',
                serial_no       TEXT NOT NULL DEFAULT '',
                source_type     TEXT NOT NULL DEFAULT 'Simulate',
                source_val      TEXT NOT NULL DEFAULT '',
                enabled         INTEGER NOT NULL DEFAULT 1,
                notes           TEXT NOT NULL DEFAULT '',
                added_at        TEXT NOT NULL DEFAULT (datetime('now','localtime')),
                group_id        INTEGER REFERENCES groups(id) ON DELETE SET NULL
            )
        """)

        existing_cols = [r["name"] for r in conn.execute(
            "PRAGMA table_info(devices)").fetchall()]
        if "group_id" not in existing_cols:
            conn.execute(
                "ALTER TABLE devices ADD COLUMN group_id INTEGER REFERENCES groups(id)")

        # ── License Settings (single-row table) ──
        conn.execute("""
            CREATE TABLE IF NOT EXISTS license_settings (
                id                  INTEGER PRIMARY KEY AUTOINCREMENT,
                is_demo             TEXT NOT NULL DEFAULT 'Yes',
                number_of_data_     INTEGER NOT NULL DEFAULT 7,
                expiry_date         DATE DEFAULT NULL,
                install_date        TEXT DEFAULT NULL,
                software_lock       TEXT NOT NULL DEFAULT 'No',
                number_of_devices   INTEGER NOT NULL DEFAULT 64
            )
        """)

        row = conn.execute(
            "SELECT COUNT(*) AS c FROM license_settings").fetchone()
        if row["c"] == 0:
            conn.execute("""
                INSERT INTO license_settings DEFAULT VALUES;
            """)

        row = conn.execute(
            "SELECT COUNT(*) AS c FROM manufacturers").fetchone()
        if row["c"] == 0:
            manufacturersrow = [
                (1, "CP Plus", "rtsp://<username>:<password>@<ip_address>:<port>/cam/realmonitor?channel=<channelNo>&subtype=0", 1),
                (2, "Dahua", "rtsp://<username>:<password>@<ip_address>:<port>/Streaming/Channels/<channelNo>01", 2),
                (3, "HiFocus", "rtsp://<username>:<password>@<ip_address>:<port>/cam/realmonitor?channel=<channelNo>&subtype=0", 3),
                (4, "Hikvision", "rtsp://<username>:<password>@<ip_address>:<port>/Streaming/Channels/<channelNo>01", 4),
                (5, "Honeywell", "rtsp://<username>:<password>@<ip_address>:<port>/rtsp/streaming?channel=01&subtype=A", 5),
                (6, "Matrix", "rtsp://<username>:<password>@<ip_address>:<port>/11", 6),
                (7, "Prama", "rtsp://<username>:<password>@<ip_address>:<port>/Streaming/Channels/<channelNo>01", 7),
                (8, "Secureye", "rtsp://<username>:<password>@<ip_address>:<port>/live/ch0", 8),
                (9, "Uniview", "rtsp://<username>:<password>@<ip_address>:<port>/media/video1", 9),
            ]
            conn.executemany("""
                INSERT INTO manufacturers (
                    id, name, streaming_url, display_order
                )
                VALUES (?, ?, ?, ?)
                """, manufacturersrow)
        conn.commit()
    finally:
        conn.close()


def change_db_password(old_password, new_password):
    conn = sqlcipher.connect(DB_FILE)
    try:
        conn.execute(f"PRAGMA key='{old_password}';")
        conn.execute(f"PRAGMA rekey='{new_password}';")
    finally:
        conn.close()


def get_all_devices(enabled_only=False):
    conn = _connect()
    try:
        if enabled_only:
            rows = conn.execute(
                "SELECT * FROM devices WHERE enabled = 1 ORDER BY channel_no ASC, id ASC"
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM devices ORDER BY channel_no ASC, id ASC"
            ).fetchall()
        return [dict(r) for r in rows]
    finally:
        conn.close()


def get_device(device_id):
    conn = _connect()
    try:
        row = conn.execute(
            "SELECT * FROM devices WHERE id = ?", (device_id,)).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def _next_channel_no(conn):
    row = conn.execute("SELECT MAX(channel_no) AS m FROM devices").fetchone()
    return (row["m"] or 0) + 1


def get_device_count():
    conn = _connect()
    try:
        row = conn.execute("SELECT COUNT(*) AS c FROM devices").fetchone()
        return row["c"]
    finally:
        conn.close()


def add_device(data: dict):
    conn = _connect()
    try:
        fields = {k: v for k, v in data.items(
        ) if k in COLUMNS and v is not None}

        if "channel_no" not in fields:
            fields["channel_no"] = _next_channel_no(conn)
        if "added_at" not in fields:
            fields["added_at"] = datetime.datetime.now().strftime(
                "%Y-%m-%d %H:%M:%S")

        cols = ", ".join(fields.keys())
        qs = ", ".join("?" for _ in fields)
        cur = conn.execute(
            f"INSERT INTO devices ({cols}) VALUES ({qs})",
            tuple(fields.values())
        )
        conn.commit()
        return cur.lastrowid
    finally:
        conn.close()


def update_device(device_id, data: dict):
    fields = {k: v for k, v in data.items() if k in COLUMNS}
    if not fields:
        return
    conn = _connect()
    try:
        set_clause = ", ".join(f"{k} = ?" for k in fields)
        conn.execute(f"UPDATE devices SET {set_clause} WHERE id = ?",
                     (*fields.values(), device_id))
        conn.commit()
    finally:
        conn.close()


def delete_device(device_id):
    conn = _connect()
    try:
        conn.execute("DELETE FROM devices WHERE id = ?", (device_id,))
        conn.commit()
    finally:
        conn.close()


def set_enabled(device_id, enabled: bool):
    update_device(device_id, {"enabled": 1 if enabled else 0})


