def update_license(data: dict):
    fields = {k: v for k, v in data.items() if k in LICENSE_COLUMNS}
    if not fields:
        return
    conn = _connect()
    try:
        row = conn.execute(
            "SELECT id FROM license_settings ORDER BY id ASC LIMIT 1").fetchone()
        if row is None:
            return
        set_clause = ", ".join(f"{k} = ?" for k in fields)
        conn.execute(f"UPDATE license_settings SET {set_clause} WHERE id = ?",
                     (*fields.values(), row["id"]))
        conn.commit()
    finally:
        conn.close()


def get_demo_expiry_date(lic: dict):
    install_date = lic.get("install_date")
    demo_days = lic.get("number_of_data_")
    if not install_date or demo_days is None:
        return None
    try:
        start = datetime.datetime.strptime(install_date, "%Y-%m-%d").date()
        return start + datetime.timedelta(days=int(demo_days))
    except Exception:
        return None


def show_custom_locked_popup(title, message, parent=None):
    if parent is None:
        try:
            parent = tk._default_root
        except Exception:
            pass
    if parent is None:
        parent = tk.Tk()
        parent.withdraw()

    # Backdrop frame to cover the entire parent and block clicks
    backdrop = tk.Frame(parent, bg="#05070B")  # very dark backdrop
    backdrop.place(x=0, y=0, relwidth=1, relheight=1)

    # Bind clicks to prevent passing through to underlying UI
    backdrop.bind("<Button-1>", lambda e: "break")
    backdrop.bind("<Key>", lambda e: "break")

    # Dialog container
    popup = tk.Frame(
        backdrop,
        bg=COLORS["bg_panel"],
        highlightthickness=1,
        highlightbackground=COLORS["border"]
    )
    popup.place(relx=0.5, rely=0.5, anchor="center", width=420, height=160)

    # Accent top border (red indicator for locks)
    tk.Frame(popup, bg=COLORS["red"], height=3).pack(fill="x")

    # Title
    tk.Label(
        popup,
        text=title.upper(),
        bg=COLORS["bg_panel"],
        fg=COLORS["red"],
        font=("Segoe UI", 10, "bold"),
        pady=10
    ).pack()

    # Message
    tk.Label(
        popup,
        text=message,
        bg=COLORS["bg_panel"],
        fg=COLORS["white"],
        font=("Segoe UI", 9),
        pady=10
    ).pack()

    # Minimal OK Button
    btn_frame = tk.Frame(popup, bg=COLORS["bg_panel"])
    btn_frame.pack(fill="x", side="bottom", pady=(0, 15))

    btn = tk.Label(
        btn_frame,
        text="OK",
        bg=COLORS["bg_card"],
        fg=COLORS["white"],
        font=("Segoe UI", 9, "bold"),
        padx=25,
        pady=6,
        cursor="hand2",
        highlightthickness=1,
        highlightbackground=COLORS["border"]
    )
    btn.pack(anchor="center")

    closed = tk.BooleanVar(value=False)

    def on_enter(e):
        btn.config(bg=COLORS["accent"], fg=COLORS["bg_dark"])

    def on_leave(e):
        btn.config(bg=COLORS["bg_card"], fg=COLORS["white"])

    btn.bind("<Enter>", on_enter)
    btn.bind("<Leave>", on_leave)

    def _close():
        backdrop.destroy()
        closed.set(True)

    btn.bind("<Button-1>", lambda e: _close())

    # Modal block wait
    parent.wait_variable(closed)


def run_startup_license_check():
    lic = get_license()
    if lic is None:
        return True

    def is_yes(val):
        return (val or "").strip().lower() == "yes"

    def is_no(val):
        return (val or "").strip().lower() == "no"

    if is_yes(lic.get("software_lock")):
        return True

    if is_no(lic.get("is_demo")):
        return True

    # 4. install_date NULL? -> install_date = today
    install_date_str = lic.get("install_date")
    if not install_date_str:
        install_date_str = datetime.date.today().strftime("%Y-%m-%d")
        update_license({"install_date": install_date_str})
        lic = get_license()

    # 5. expiry_date NULL? -> expiry_date = install_date + demo_days
    expiry_date_str = lic.get("expiry_date")
    if not expiry_date_str:
        demo_days = lic.get("number_of_data_")
        if demo_days is None:
            demo_days = 1
        try:
            start_date = datetime.datetime.strptime(
                install_date_str, "%Y-%m-%d").date()
            expiry_date = start_date + datetime.timedelta(days=int(demo_days))
            expiry_date_str = expiry_date.strftime("%Y-%m-%d")
            update_license({"expiry_date": expiry_date_str})
            lic = get_license()
        except Exception:
            pass

    # 6. today >= expiry? -> software_lock = Yes
    if expiry_date_str:
        try:
            today = datetime.date.today()
            expiry_date = datetime.datetime.strptime(
                expiry_date_str, "%Y-%m-%d").date()
            if today >= expiry_date:
                update_license({"software_lock": "Yes"})
        except Exception:
            pass

    return True


