def _auth_get_connection():
    return mysql.connector.connect(**AUTH_DB_CONFIG)


def get_mac_address() -> str:
    """இந்த machine-ஓட MAC address-ஐ AA:BB:CC:DD:EE:FF வடிவில் தரும்."""
    mac_num = uuid.getnode()
    return ":".join(f"{(mac_num >> ele) & 0xff:02X}" for ele in range(40, -8, -8))


def _hash_password(password: str) -> str:
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


_USERNAME_RE = re.compile(r"^[A-Za-z0-9_.]{4,50}$")
_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def _validate_registration(username, email, password, confirm_password):
    if not _USERNAME_RE.match(username or ""):
        return "Username must be 4-50 chars: letters, numbers, '_' or '.' only."
    if not _EMAIL_RE.match(email or ""):
        return "Enter a valid email address."
    if len(password) < 6:
        return "Password must be at least 6 characters."
    if password != confirm_password:
        return "Password and Confirm Password do not match."
    return None


def register_user(username, email, password, confirm_password):
    """Returns (ok: bool, message: str). MAC is fetched automatically — never asked in the UI."""
    err = _validate_registration(username, email, password, confirm_password)
    if err:
        return False, err

    mac = get_mac_address()
    hashed_pw = _hash_password(password)

    try:
        conn = _auth_get_connection()
    except MySQLError as e:
        return False, f"Database connection failed: {e}"

    cursor = conn.cursor()
    try:
        cursor.execute("SELECT id FROM register WHERE username = %s", (username,))
        if cursor.fetchone():
            return False, "That username is already taken."

        cursor.execute("SELECT id FROM register WHERE email = %s", (email,))
        if cursor.fetchone():
            return False, "That email is already registered."

        cursor.execute(
            """INSERT INTO register
               (username, email, password, mac_address)
               VALUES (%s, %s, %s, %s)""",
            (username, email.strip(), hashed_pw, mac),
        )
        cursor.execute(
            "INSERT INTO active_user_list (email, status) VALUES (%s, 'Active')",
            (email.strip(),),
        )
        conn.commit()
        return True, "Registration successful. You can log in now."
    except MySQLError as e:
        conn.rollback()
        return False, f"Registration failed: {e}"
    finally:
        cursor.close()
        conn.close()


def reset_password_by_email(email, new_password, confirm_password):
    """Returns (ok: bool, message: str).

    Forgot-Password flow:
      1. Look up the account by EMAIL (not username).
      2. Compare the MAC address stored for that email against THIS
         machine's current MAC address.
      3. Only if they match, overwrite the password.

    This means a password can only be reset from the same computer the
    account was originally registered/licensed on — resetting from a
    different PC is refused even with the correct email.
    """
    if not email or not email.strip():
        return False, "Enter your registered email."
    if len(new_password) < 6:
        return False, "New password must be at least 6 characters."
    if new_password != confirm_password:
        return False, "New Password and Confirm Password do not match."

    current_mac = get_mac_address()
    hashed_pw = _hash_password(new_password)

    try:
        conn = _auth_get_connection()
    except MySQLError as e:
        return False, f"Database connection failed: {e}"

    cursor = conn.cursor(dictionary=True)
    try:
        cursor.execute(
            "SELECT username, mac_address FROM register WHERE email = %s",
            (email.strip(),),
        )
        row = cursor.fetchone()
        if row is None:
            # Generic message — don't reveal whether the email exists.
            return False, "No matching account found for this email on this computer."

        if row["mac_address"] != current_mac:
            return False, "This computer is not the registered device for this email."

        cursor.execute(
            "UPDATE register SET password = %s WHERE email = %s",
            (hashed_pw, email.strip()),
        )
        conn.commit()
        return True, "Password reset successfully. You can log in now."
    except MySQLError as e:
        conn.rollback()
        return False, f"Password reset failed: {e}"
    finally:
        cursor.close()
        conn.close()


def login_user(email, password):
    """Returns (ok: bool, message: str). email+password+MAC ALL must match, and status must be Active."""
    if not email or not password:
        return False, "Enter both email and password."

    current_mac = get_mac_address()
    hashed_pw = _hash_password(password)

    try:
        conn = _auth_get_connection()
    except MySQLError as e:
        return False, f"Database connection failed: {e}"

    cursor = conn.cursor(dictionary=True)
    try:
        cursor.execute(
            "SELECT username, email, password, mac_address FROM register WHERE email = %s",
            (email,),
        )
        row = cursor.fetchone()
        if row is None or row["password"] != hashed_pw:
            return False, "Invalid email or password."

        if row["mac_address"] != current_mac:
            return False, "This account is not licensed for this computer."

        # active_user_list is keyed by email (per the live table's FK), not username.
        cursor.execute("SELECT status FROM active_user_list WHERE email = %s", (row["email"],))
        status_row = cursor.fetchone()
        if status_row is None or (status_row["status"] or "").strip().lower() != "active":
            return False, "This account is inactive. Contact your administrator."

        return True, "Login successful."
    except MySQLError as e:
        return False, f"Login failed: {e}"
    finally:
        cursor.close()
        conn.close()


