def add_group(name):
    name = (name or "").strip()
    if not name:
        return None
    conn = _connect()
    try:
        cur = conn.execute(
            "INSERT OR IGNORE INTO groups (name) VALUES (?)", (name,))
        conn.commit()
        if cur.lastrowid:
            return cur.lastrowid
        row = conn.execute(
            "SELECT id FROM groups WHERE name = ?", (name,)).fetchone()
        return row["id"] if row else None
    finally:
        conn.close()


