# ─────────────────────────────────────────────
class VMSApp:
    def __init__(self, root: tk.Tk):
        self.root = root
        self.root.report_callback_exception = self._handle_tk_exception
        self.root.title(
            "Camlytix® VMS — Video Management Software 1.0  |  DO365 Technologies Pvt Ltd  |  Call for support: +919092222016")
        self.root.geometry("1400x820")
        self.root.minsize(900, 600)
        self.root.configure(bg=COLORS["bg_dark"])

        self.channel_count = 16
        self.cameras: list[CameraSource] = []
        self.tiles:   list[ChannelTile] = []
        self.selected_ch = 0
        self.running = False
        self._feed_thread = None
        self.fullscreen_ch = None
        self.fs_window = None
        self.events = []
        self.filter_mode = "all"
        self.active_tab = "live"

        self._ch_vars:       list[tk.BooleanVar] = []
        self._ch_row_frames: list[tk.Frame] = []
        self._search_var = tk.StringVar()

        self.group_filter = None
        self._group_id_by_name = {}

        self.cycle_index = 0
        self.cycle_running = True
        self.cycle_interval_ms = 30000
        self._cycle_after_id = None
        self.theme = "dark"
        self._theme_protected_widgets = set()
        self._accordion_sections = {}
        self._status_dots = []
        # ── Licensing state ──
        self.license = get_license() or {}
        self.software_locked = (self.license.get(
            "software_lock") or "").strip().lower() == "yes"

        self._schedule_cycle_tick()

        self._build_ui()
        self._apply_license_ui()
        if self.software_locked:
            self._show_license_locked_popup()
        self._init_cameras()
        self._start_feed()

    def _handle_tk_exception(self, exc_type, exc_value, exc_tb):
        try:
            msg = "".join(traceback.format_exception(
                exc_type, exc_value, exc_tb))
            _log_crash("Tk callback error", msg)
            self._log(
                "⚠ Internal error recovered — see CameraData/crash.log",
                event_type="ERROR")
        except Exception:
            pass

    # ══════════════════════════════════════════
    #  LICENSING
    # ══════════════════════════════════════════
    def _apply_license_ui(self):
        is_demo = (self.license.get("is_demo") or "").strip().lower() == "yes"
        if hasattr(self, "lbl_demo_badge"):
            if is_demo:
                self.lbl_demo_badge.pack(side="left", padx=(4, 0))
                dt = datetime.datetime.strptime(
                    self.license.get("expiry_date"), "%Y-%m-%d")
                formatted = dt.strftime("%a, %d %b %Y")
                self.lbl_demo_badge.config(
                    text="⚠ Trail Pack upto " + formatted)
            else:
                self.lbl_demo_badge.pack_forget()

    def _show_license_locked_popup(self):
        show_custom_locked_popup(
            "Software Locked", "Do365 Technologies Pvt Ltd | Call for support: +919092222016", parent=self.root)
        sys.exit(0)

    def get_camera_limit(self):
        """Number of Cameras column value, or None if not set (unlimited)."""
        n = self.license.get("number_of_devices")
        return int(n) if n is not None else None

    def can_add_camera(self):
        limit = self.get_camera_limit()
        if limit is None:
            return True
        current = get_device_count()
        if current >= limit:
            messagebox.showwarning("Camera Limit Reached",
                                   "Maximum camera limit reached. Contact DO365.")
            return False
        return True

    # ══════════════════════════════════════════
    #  UI
    # ══════════════════════════════════════════
    def _build_ui(self):
        self._build_header()
        self._build_tabbar()
        content = tk.Frame(self.root, bg=COLORS["bg_dark"])
        content.pack(fill="both", expand=True)
        self._build_sidebar(content)
        self._content_frame = content
        self._build_main(content)

    def start_camera_loading(self):
        threading.Thread(
            target=self.load_cameras,
            daemon=True
        ).start()

    def load_cameras(self):
        self._init_cameras()
        self.root.after(
            0,
            self._start_feed
        )

    # ── Online/Offline count ────────────────────────────────
    def update_camera_counts(self):

        online = 0
        offline = 0

        for cam in self.cameras:

            cam.check_status()

            if cam.connected:
                online += 1
            else:
                offline += 1

        if hasattr(self, "lbl_all_devices"):
            self.lbl_all_devices.config(
                text=f"All Devices: {len(self.cameras)}")
        if hasattr(self, "lbl_online_devices"):
            self.lbl_online_devices.config(text=f"Online Devices: {online}")

        self._update_filter_button_counts(len(self.cameras), online, offline)

    def _update_filter_button_counts(self, total, online, offline):
        if hasattr(self, "btn_all"):
            self.btn_all.config(text=f"All ({total})")
        if hasattr(self, "btn_online"):
            self.btn_online.config(text=f"Online ({online})")
        if hasattr(self, "btn_offline"):
            self.btn_offline.config(text=f"Offline ({offline})")

        for idx, cam in enumerate(self.cameras):
            cam.connect
            if cam.connected:
                # Camera 0 connected
                self._status_dots[idx].config(fg="green")
            else:
                # Camera 1 disconnected
                self._status_dots[idx].config(fg="red")

    def set_filter(self, mode):
        self.filter_mode = mode
        self.highlight_filter_button(mode)
        self.refresh_channel_filter()

    def refresh_channel_filter(self):
        query = self._search_var.get().lower()

        for idx, row in enumerate(self._ch_row_frames):

            cam = self.cameras[idx]

            show = True

            if self.filter_mode == "online":
                show = cam.connected
            elif self.filter_mode == "offline":
                show = not cam.connected

            if query:
                if query not in cam.name.lower():
                    show = False

            if show:
                row.pack(fill="x", pady=1)
            else:
                row.pack_forget()

    # ── Header ────────────────────────────────
    def _build_header(self):
        hdr = tk.Frame(self.root, bg=COLORS["bg_header"], height=52)
        hdr.pack(fill="x")
        hdr.pack_propagate(False)

        left = tk.Frame(hdr, bg=COLORS["bg_header"])
        left.pack(side="left", fill="y")

        self._logo_height = 76
        self.logo_label = None
        try:
            composed = _compose_logo_image(
                self.theme, COLORS["bg_header"], self._logo_height)
            logo_tk = ImageTk.PhotoImage(composed)
            lbl = tk.Label(left, image=logo_tk, bg=COLORS["bg_header"], bd=0)
            lbl.image = logo_tk
            lbl.pack(side="left", padx=(14, 8), pady=6)
            self.logo_label = lbl
            self._theme_protected_widgets.add(lbl)
        except Exception:
            tk.Label(left, text="◉", bg=COLORS["bg_header"],
                     fg=COLORS["accent"],
                     font=("Courier New", 22, "bold")).pack(side="left", padx=(14, 8), pady=6)

        # ── DEMO badge — only shown when license.is_demo == 'Yes' ──
        self.lbl_demo_badge = tk.Label(left, text="⚠ Trail Pack", bg=COLORS["red"],
                                       fg="#DEEC0D", font=(FONTS["label"], 12, "bold"),
                                       padx=8, pady=3)

        self._theme_protected_widgets.add(self.lbl_demo_badge)
        # Not packed here — _apply_license_ui() decides visibility.

        # ── Tabs: Live View / Device List / Event Log — in the main bar ──
        self.tab_buttons = {}
        tabs = [
            ("live",    "▶  Live View"),
            ("devices", "☰  Device List"),
            ("events",  "⚑  Event Log"),
        ]
        for key, label in tabs:
            b = tk.Button(left, text=label, bg=COLORS["bg_header"], fg=COLORS["gray_light"],
                          font=FONTS["body"], relief="flat", bd=0, padx=14, pady=6,
                          cursor="hand2", activebackground=COLORS["bg_card"],
                          activeforeground=COLORS["accent"],
                          command=lambda k=key: self.show_tab(k))
            b.pack(side="left", padx=2)
            self.tab_buttons[key] = b
            self._theme_protected_widgets.add(b)

         # ── Date & Time — right side of the main bar ──
        self.lbl_clock = tk.Label(hdr, text="", bg=COLORS["bg_header"],
                                  fg=COLORS["accent"], font=FONTS["time"])
        self.lbl_clock.pack(side="right", padx=10)
        self._tick_clock()

        self.btn_theme = tk.Button(hdr, text="🌙 Dark", bg=COLORS["bg_card"],
                                   fg=COLORS["white"], font=FONTS["label"],
                                   relief="flat", padx=10, pady=4, cursor="hand2",
                                   activebackground=COLORS["accent"], activeforeground="#000",
                                   command=self._toggle_theme)
        self.btn_theme.pack(side="right", padx=6)

        self.btn_about = tk.Button(hdr, text="ℹ About", bg=COLORS["bg_card"],
                                   fg=COLORS["white"], font=FONTS["label"],
                                   relief="flat", padx=10, pady=4, cursor="hand2",
                                   activebackground=COLORS["accent"], activeforeground="#000",
                                   command=self._show_about)
        self.btn_about.pack(side="right", padx=6)

    # ── Tab bar (Group Filter/Layout/Preview) ────────

    def blink_label(self):
        current = self.lbl_demo_badge.cget("fg")

        if current == COLORS["red"]:
            self.lbl_demo_badge.config(fg="#1A1A1A")
        else:
            self.lbl_demo_badge.config(fg=COLORS["red"])

        self.lbl_demo_badge.after(
            500, self.blink_label(self))   # Blink every 500 ms

    def _build_tabbar(self):
        bar = tk.Frame(self.root, bg=COLORS["bg_panel"], height=40)
        bar.pack(fill="x")
        bar.pack_propagate(False)
        self.tabbar_frame = bar   # ← reference to hide/show later

        # ── Group filter ──
        tk.Label(bar, text="Camera Group:", bg=COLORS["bg_panel"],
                 fg=COLORS["gray_light"], font=FONTS["label"]).pack(side="left", padx=(12, 4))

        self._group_var = tk.StringVar(value="All")
        self.group_combo = ttk.Combobox(bar, textvariable=self._group_var, state="readonly",
                                        width=35, values=["All"])
        self.group_combo.pack(side="left", padx=(0, 4))
        self.group_combo.bind("<<ComboboxSelected>>",
                              self._on_group_combo_selected)

        self._div(bar)

        # ── Layout switch ──
        tk.Label(bar, text="Grid:", bg=COLORS["bg_panel"],
                 fg=COLORS["gray_light"], font=FONTS["label"]).pack(side="left", padx=4)
        self.layout_buttons = {}
        for n in (2, 4, 8, 16, 32, 64):
            btn = tk.Button(bar, text=f"⊞ {n}",
                            bg=COLORS["bg_card"], fg=COLORS["white"],
                            font=FONTS["body"], relief="flat", padx=10, pady=3,
                            cursor="hand2",
                            activebackground=COLORS["accent"], activeforeground="#000",
                            command=lambda x=n: self._switch_layout(x))
            btn.pack(side="left", padx=2)
            self.layout_buttons[n] = btn
            self._theme_protected_widgets.add(btn)

        # ── Camera cycling controls (right-aligned, end of tab bar) ──
        self._build_cycle_controls(bar)
        self._highlight_layout_buttons()

    def _build_cycle_controls(self, bar):
        cyc = tk.Frame(bar, bg=COLORS["bg_panel"])
        cyc.pack(side="right", padx=10)

        self.lbl_cycle_range = tk.Label(cyc, text="", bg=COLORS["bg_panel"],
                                        fg=COLORS["accent"], font=FONTS["label"])
        self.lbl_cycle_range.pack(side="right", padx=(8, 4))

        self._interval_var = tk.StringVar(value="30s")
        interval_combo = ttk.Combobox(cyc, textvariable=self._interval_var, state="readonly",
                                      width=5, values=["20s", "30s", "60s", "120s"])
        interval_combo.pack(side="right", padx=(0, 4))
        interval_combo.bind("<<ComboboxSelected>>", self._on_interval_change)

        tk.Label(cyc, text="Interval:", bg=COLORS["bg_panel"],
                 fg=COLORS["gray_light"], font=FONTS["label"]).pack(side="right", padx=(8, 2))

        self.btn_cycle_pause = tk.Button(cyc, text="⏸ Pause",
                                         font=FONTS["label"],
                                         relief="flat", padx=10, pady=4, cursor="hand2",
                                         command=self._pause_cycle)
        self.btn_cycle_pause.pack(side="right", padx=2)

        self.btn_cycle_play = tk.Button(cyc, text="▶ Play",
                                        font=FONTS["label"],
                                        relief="flat", padx=10, pady=4, cursor="hand2",
                                        command=self._play_cycle)
        self.btn_cycle_play.pack(side="right", padx=2)
        
