    def show_tab(self, key):
        self.active_tab = key
        for k, b in self.tab_buttons.items():
            if k == key:
                b.config(fg=COLORS["accent"], bg=COLORS["accent_dim"])
            else:
                b.config(fg=COLORS["gray_light"], bg=COLORS["bg_header"])

        for frame in (self.live_view_frame, self.device_list_frame, self.event_log_frame):
            frame.pack_forget()

        if key == "live":
            if not self.sidebar_frame.winfo_ismapped():
                self.sidebar_frame.pack(
                    side="left", fill="y", before=self.main_frame)
        else:
            self.sidebar_frame.pack_forget()

        if key == "live":
            if not self.tabbar_frame.winfo_ismapped():
                self.tabbar_frame.pack(fill="x", before=self._content_frame)
        else:
            self.tabbar_frame.pack_forget()

        if key == "live":
            self.live_view_frame.pack(fill="both", expand=True)
        elif key == "devices":
            self.device_list_frame.pack(fill="both", expand=True)
            self.refresh_device_list()
        elif key == "events":
            self.event_log_frame.pack(fill="both", expand=True)
            self.refresh_event_log_view()

