    def _on_search_change(self, *_):
        query = self._search_var.get().lower().strip()
        for idx, row in enumerate(self._ch_row_frames):
            cam = self.cameras[idx]
            match = (query == "" or
                     query in cam.name.lower() or
                     query in f"ch{idx+1:02d}")
            if match:
                row.pack(fill="x", pady=1)
            else:
                row.pack_forget()

    # ══════════════════════════════════════════
    #  AUTO-CYCLE (Play / Pause / interval)
    # ══════════════════════════════════════════
    def _play_cycle(self):
        self.cycle_running = True
        self._update_cycle_buttons()
        self._schedule_cycle_tick()

    def _pause_cycle(self):
        self.cycle_running = False
        self._update_cycle_buttons()
        if self._cycle_after_id is not None:
            self.root.after_cancel(self._cycle_after_id)
            self._cycle_after_id = None

    def _update_cycle_buttons(self):
        if self.cycle_running:
            self.btn_cycle_play.config(bg=COLORS["accent"], fg=COLORS["bg_dark"],
                                       activebackground=COLORS["accent"],
                                       activeforeground=COLORS["bg_dark"])
            self.btn_cycle_pause.config(bg=COLORS["bg_dark"], fg=COLORS["white"],
                                        activebackground=COLORS["red"],
                                        activeforeground=COLORS["white"])
        else:
            self.btn_cycle_pause.config(bg=COLORS["red"], fg=COLORS["white"],
                                        activebackground=COLORS["red"],
                                        activeforeground=COLORS["white"])
            self.btn_cycle_play.config(bg=COLORS["bg_dark"], fg=COLORS["white"],
                                       activebackground=COLORS["accent"],
                                       activeforeground=COLORS["bg_dark"])

    def _on_interval_change(self, event=None):
        s = self._interval_var.get()
        try:
            secs = int(s.rstrip("s"))
        except ValueError:
            secs = 5
        self.cycle_interval_ms = secs * 1000
        if self.cycle_running:
            self._schedule_cycle_tick()

    def _schedule_cycle_tick(self):
        if self._cycle_after_id is not None:
            self.root.after_cancel(self._cycle_after_id)
            self._cycle_after_id = None
        if not self.cycle_running:
            return
        self._cycle_after_id = self.root.after(
            self.cycle_interval_ms, self._cycle_tick)

    def _cycle_tick(self):
        self._cycle_after_id = None
        if not self.cycle_running:
            return
        try:
            self._advance_cycle_page()
        except Exception:
            _log_crash("_advance_cycle_page failed")
            self._log(
                "⚠ Cycle page error recovered — see crash.log",
                event_type="ERROR")
        finally:
            self._schedule_cycle_tick()

    def _advance_cycle_page(self):
        cams = self._get_filtered_cameras()
        total = len(cams)
        if total == 0:
            self.cycle_index = 0
            return
        page_size = max(1, self.channel_count)
        num_pages = math.ceil(total / page_size)

        if num_pages <= 1:
            # Nothing to cycle to — don't tear down/rebuild tiles for no reason.
            return

        current_page = self.cycle_index // page_size
        next_page = (current_page + 1) % num_pages
        self.cycle_index = next_page * page_size
        self._rebuild_grid()
        
    def _retreat_cycle_page(self):
            if self.cycle_running:
                self._pause_cycle()
            cams = self._get_filtered_cameras()
            total = len(cams)
            if total == 0:
                self.cycle_index = 0
                return
            page_size = max(1, self.channel_count)
            num_pages = math.ceil(total / page_size)
    
            if num_pages <= 1:
                return
    
            current_page = self.cycle_index // page_size
            prev_page = (current_page - 1) % num_pages
            self.cycle_index = prev_page * page_size
            self._rebuild_grid()
        
    def _next_cycle_page(self):
            if self.cycle_running:
                self._pause_cycle()        
            try:
                self._advance_cycle_page()
            except Exception:
                _log_crash("_next_cycle_page failed")
                self._log(
                    "⚠ Page navigation error recovered — see crash.log",
                    event_type="ERROR")
    

    def _update_cycle_range_label(self, start, end, total):
        page_size = max(1, self.channel_count)              
        num_pages = max(1, math.ceil(total / page_size))    
        current_page = (start // page_size) + 1
        self.lbl_cycle_range.config(text=f"Page {current_page} of {num_pages}")
        rows, cols = LAYOUTS.get(self.channel_count, (4, 4))
        if total == 0:
            self.lbl_ch_count.config(text="No channels selected")
            return
        self.lbl_ch_count.config(
            text=f"Cameras {start+1}-{end} of {total}   ({end}/{total})   |  {rows}×{cols}")

    # ══════════════════════════════════════════
    #  LAYOUT BUTTON HIGHLIGHT (2/4/8/16/32/64)
    # ══════════════════════════════════════════
    def _highlight_layout_buttons(self):
        if not hasattr(self, "layout_buttons"):
            return
        for n, btn in self.layout_buttons.items():
            if n == self.channel_count:
                btn.config(bg=COLORS["accent"], fg=COLORS["bg_dark"],
                           activebackground=COLORS["accent"], activeforeground=COLORS["bg_dark"])
            else:
                btn.config(bg=COLORS["bg_card"], fg=COLORS["white"],
                           activebackground=COLORS["accent"], activeforeground="#000")

    # ══════════════════════════════════════════
    #  GROUP FILTER LOGIC (header-bar combobox)
    # ══════════════════════════════════════════
    def _refresh_group_combo(self):
        if not hasattr(self, "group_combo"):
            return

        groups = get_all_groups()
        self._group_id_by_name = {g["name"]: g["id"] for g in groups}

        values = ["All"] + [g["name"] for g in groups]
        self.group_combo.config(values=values)

        current_name = next((name for name, gid in self._group_id_by_name.items()
                             if gid == self.group_filter), "All")
        if current_name not in values:
            current_name = "All"
        self._group_var.set(current_name)

    def _on_group_combo_selected(self, event=None):
        name = self._group_var.get()
        gid = None if name == "All" else self._group_id_by_name.get(name)
        self.set_group_filter(gid)

    def set_group_filter(self, group_id):
        self.group_filter = group_id
        self._refresh_group_combo()
        self._apply_channel_visibility()

    def _get_filtered_cameras(self):
        cams = self.cameras

        if self._ch_vars and len(self._ch_vars) == len(self.cameras):
            cams = [cam for i, cam in enumerate(
                cams) if self._ch_vars[i].get()]

        if self.group_filter is not None:
            cams = [cam for cam in cams if cam.group_id == self.group_filter]

        return cams

    def _apply_channel_visibility(self):
        visible = self._get_filtered_cameras()

        self.running = False

        for w in self.grid_frame.winfo_children():
            w.destroy()
        self.tiles.clear()

        visible = visible[: self.channel_count]
        n = len(visible)
        if n == 0:
            self.lbl_ch_count.config(text="No channels selected")
            return

        rows, cols = LAYOUTS.get(self.channel_count, (4, 4))

        for r in range(10):
            self.grid_frame.rowconfigure(r, weight=0)
        for c in range(10):
            self.grid_frame.columnconfigure(c, weight=0)

        for r in range(rows):
            self.grid_frame.rowconfigure(r, weight=1)
        for c in range(cols):
            self.grid_frame.columnconfigure(c, weight=1)

        for ti, cam in enumerate(visible):
            r, c = divmod(ti, cols)
            tile = ChannelTile(self.grid_frame, cam, self)
            tile.grid(row=r, column=c, sticky="nsew", padx=2, pady=2)
            self.tiles.append(tile)

        self.lbl_ch_count.config(
            text=f"{n} Channel(s) Visible  |  {rows}×{cols}")

        for tile in self.tiles:
            tile.set_selected(tile.cam.channel_id == self.selected_ch)

        self.cycle_index = 0
        self._rebuild_grid()
        self._start_feed()

    # ══════════════════════════════════════════
    #  CAMERA INIT  — loads every enabled row from the devices SQLite table
    # ══════════════════════════════════════════
    def _init_cameras(self):
        for cam in self.cameras:
            cam.disconnect()
        self.cameras.clear()

        rows = get_all_devices(enabled_only=True)
        group_map = {g["id"]: g["name"] for g in get_all_groups()}

        for i, row in enumerate(rows):
            name = row.get("name") or f"Camera {i+1}"
            effective_type, source = resolve_source(row)
            gid = row.get("group_id")
            cam = CameraSource(
                i, name=name, source=source,
                device_id=row.get("id"),
                ip=row.get("ip"),
                channel_no=row.get("channel_no"),
                port=row.get("port"),
                username=row.get("username"),
                password=row.get("password"),
                device_type=row.get("device_type"),
                model=row.get("model"),
                manufacturer=row.get("manufacturer"),
                location=row.get("location"),
                serial_no=row.get("serial_no"),
                source_type=row.get("source_type"),
                effective_source_type=effective_type,
                source_val=row.get("source_val"),
                enabled=row.get("enabled"),
                notes=row.get("notes"),
                added_at=row.get("added_at"),
                group_id=gid,
                group_name=group_map.get(gid, ""),
            )
            ok = cam.connect()
            if not ok:
                cam.status = "Offline"
                cam.connected = False
                self._log(f"⚠ CH{i+1:02d} Offline",
                          event_type="OFFLINE", device=name)
            else:
                self._log(f"✓ CH{i+1:02d} {name} connected",
                          event_type="CONNECT", device=name)
            self.cameras.append(cam)

        if not self.cameras:
            self._log("No enabled devices in 'devices' table — use Device List → + Add",
                      event_type="INFO")

        self._build_channel_checklist()
        self._refresh_group_combo()
        self._rebuild_grid()
        self.refresh_device_list()
        self._refresh_group_combo()

    def _reload_cameras_from_db(self):
        self._init_cameras()

    # ══════════════════════════════════════════
    #  GRID  (used by init + layout switch)
    # ══════════════════════════════════════════
    def _rebuild_grid(self):
        all_cams = self._get_filtered_cameras()
        total = len(all_cams)
        page_size = max(1, self.channel_count)

        if total == 0 or self.cycle_index >= total:
            self.cycle_index = 0

        start = self.cycle_index
        end = min(start + page_size, total)
        visible_cams = all_cams[start:end]
        if self.tiles and getattr(self, "_last_visible_cams", None) == visible_cams:
            self._update_cycle_range_label(start, end, total)
            return

        self.running = False
        for w in self.grid_frame.winfo_children():
            w.destroy()
        self.tiles.clear()

        rows, cols = LAYOUTS.get(self.channel_count, (4, 4))

        for r in range(10):
            self.grid_frame.rowconfigure(r, weight=0)
        for c in range(10):
            self.grid_frame.columnconfigure(c, weight=0)
        for r in range(rows):
            self.grid_frame.rowconfigure(r, weight=1)
        for c in range(cols):
            self.grid_frame.columnconfigure(c, weight=1)

        self._last_visible_cams = visible_cams

        for idx, cam in enumerate(visible_cams):
            r, c = divmod(idx, cols)
            tile = ChannelTile(self.grid_frame, cam, self)
            tile.grid(row=r, column=c, sticky="nsew", padx=2, pady=2)
            self.tiles.append(tile)

        self.grid_frame.update_idletasks()
        self._update_all_tiles()

        self._update_cycle_range_label(start, end, total)

        if self.selected_ch < len(self.cameras):
            self.select_channel(self.selected_ch)
        self._log(
            f"Grid: {self.channel_count}-channel ({rows}×{cols})", event_type="LAYOUT")
        self._start_feed()

    def _switch_layout(self, n):
        if n == self.channel_count:
            return
        self.channel_count = n
        self.cycle_index = 0
        self._highlight_layout_buttons()
        self._rebuild_grid()

    # ══════════════════════════════════════════
    #  FEED LOOP  — single thread, restartable
    # ══════════════════════════════════════════
    def _start_feed(self):
        self.running = True

        if getattr(self, "_feed_active", False):
            return

        self._feed_active = True

        self.root.after(100, self._feed_loop)

    def _feed_loop(self):
        if not self.running:
            self._feed_active = False
            return

        try:
            self._update_all_tiles()
            self.update_camera_counts()
        except Exception:
            _log_crash("_feed_loop tile update failed")

        self.root.after(1000, self._feed_loop)

    def _update_all_tiles(self):
        tiles = list(self.tiles)
        if not tiles:
            return
        cw_ref = self.grid_frame.winfo_width()
        ch_ref = self.grid_frame.winfo_height()
        n = len(tiles)
        keys = sorted(LAYOUTS.keys())
        layout_key = next((k for k in keys if k >= n), keys[-1])
        _, cols = LAYOUTS[layout_key]
        tw = max(80, (cw_ref - cols*4) // cols)
        rows = math.ceil(n / cols)
        th = max(60, (ch_ref - rows*4) // rows)

        for tile in tiles:
            frame = tile.cam.get_frame(tw, th)
            tile.cam.check_status()
            try:
                tile.update_frame(frame)
                tile.refresh_meta()
            except Exception:
                pass

    # ══════════════════════════════════════════
    #  CHANNEL SELECTION / FULLSCREEN
    # ══════════════════════════════════════════
    def select_channel(self, idx):
        if idx == self.selected_ch:
            return
        self.selected_ch = idx
        for tile in self.tiles:
            tile.set_selected(False)
        for tile in self.tiles:
            if tile.cam.channel_id == idx:
                tile.set_selected(True)
                break
        if idx < len(self.cameras):
            cam = self.cameras[idx]
            self.lbl_sel_name.config(
                text=f"CH{idx+1:02d} — {cam.name}"
            )
            color = {
                "Live": COLORS["green"],
                "Offline": COLORS["red"],
                "Idle": COLORS["gray"]
            }.get(cam.status, COLORS["gray"])
            self.lbl_sel_status.config(
                text=f"● {cam.status}",
                fg=color
            )

    def fullscreen_channel(self, idx):
        if self.fs_window and self.fs_window.winfo_exists():
            self.fs_window.destroy()

        cam = self.cameras[idx]

        win = tk.Toplevel(self.root)
        win.title(f"CH{idx+1:02d} — {cam.name} (Fullscreen)")
        win.geometry("1200x750")
        win.configure(bg="#000")
        self.fs_window = win

        BASE_PATH = get_app_data_dir()

        SCREENSHOT_DIR = os.path.join(BASE_PATH, "Screenshots")
        RECORDING_DIR = os.path.join(BASE_PATH, "Recordings")

        os.makedirs(SCREENSHOT_DIR, exist_ok=True)
        os.makedirs(RECORDING_DIR, exist_ok=True)

        tk.Label(win, text=f"CH{idx+1:02d}  {cam.name}  |  Double-click video to close",
                 bg="#111", fg=COLORS["accent"], font=FONTS["body"]).pack(fill="x")

        canvas = tk.Canvas(win, bg="#000", highlightthickness=0)
        canvas.pack(fill="both", expand=True)

        ctrl = tk.Frame(win, bg=COLORS["bg_header"], height=42)
        ctrl.pack(fill="x", side="bottom")
        ctrl.pack_propagate(False)

        rec_state = {"writer": None, "recording": False, "path": None}

        lbl_info = tk.Label(ctrl, text="", bg=COLORS["bg_header"],
                            fg=COLORS["gray_light"], font=FONTS["small"])
        lbl_info.pack(side="right", padx=10)

        def take_screenshot():
            frame = cam.get_frame(canvas.winfo_width() or 640,
                                  canvas.winfo_height() or 480)
            if frame is None:
                return
            ts = datetime.datetime.now().strftime("%Y-%m-%d_%H.%M.%S")

            img = Image.fromarray(frame)
            draw = ImageDraw.Draw(img)
            draw.text((10, 10), datetime.datetime.now().strftime("%Y-%m-%d  %H:%M:%S"),
                      fill=(0, 200, 255))
            draw.text((10, 30), cam.name, fill=(200, 220, 240))
            frame = np.array(img)

            channel_name = "".join(c if c.isalnum() or c in (
                " ", "_", "-") else "_" for c in cam.name).strip()
            channel_name = channel_name.replace(" ", "_")

            fname = os.path.join(
                SCREENSHOT_DIR,
                f"CH{idx+1}_{channel_name}_{ts}.png"
            )
            bgr = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
            cv2.imwrite(fname, bgr)
            lbl_info.config(
                text=f"Saved screenshot: {os.path.basename(fname)}")
            self._log(f"📷 Screenshot saved: {fname}",
                      event_type="SNAPSHOT", device=cam.name)

        def toggle_record():
            if not rec_state["recording"]:
                ts = datetime.datetime.now().strftime("%Y-%m-%d_%H.%M.%S")

                channel_name = "".join(c if c.isalnum() or c in (
                    " ", "_", "-") else "_" for c in cam.name).strip()
                channel_name = channel_name.replace(" ", "_")

                fname = os.path.join(
                    RECORDING_DIR,
                    f"CH{idx+1}_{channel_name}_{ts}.mp4"
                )
                w = canvas.winfo_width() or 640
                h = canvas.winfo_height() or 480
                fourcc = cv2.VideoWriter_fourcc(*"mp4v")
                writer = cv2.VideoWriter(fname, fourcc, 20.0, (w, h))
                rec_state["writer"] = writer
                rec_state["recording"] = True
                rec_state["path"] = fname
                rec_state["size"] = (w, h)
                btn_rec.config(text="⏹ Stop Recording", bg=COLORS["red"])
                lbl_info.config(text=f"Recording: {os.path.basename(fname)}")
                self._log(f"Recording: {cam.name}",
                          event_type="REC_START", device=cam.name)
            else:
                rec_state["recording"] = False
                if rec_state["writer"] is not None:
                    rec_state["writer"].release()
                    rec_state["writer"] = None
                btn_rec.config(text="⏺ Record", bg=COLORS["bg_card"])
                lbl_info.config(
                    text=f"Saved recording: {os.path.basename(rec_state['path'] or '')}")
                self._log(f"Stopped: {cam.name}",
                          event_type="REC_STOP", device=cam.name)

        btn_shot = tk.Button(ctrl, text="📷 Screenshot",
                             bg=COLORS["bg_card"], fg=COLORS["white"],
                             font=FONTS["body"], relief="flat", padx=14, pady=6,
                             cursor="hand2",
                             activebackground=COLORS["accent"], activeforeground="#000",
                             command=take_screenshot)
        btn_shot.pack(side="left", padx=8, pady=4)

        btn_rec = tk.Button(ctrl, text="⏺ Record",
                            bg=COLORS["bg_card"], fg=COLORS["white"],
                            font=FONTS["body"], relief="flat", padx=14, pady=6,
                            cursor="hand2",
                            activebackground=COLORS["accent"], activeforeground="#000",
                            command=toggle_record)
        btn_rec.pack(side="left", padx=8, pady=4)

        ph = [None]

        def fs_update():
            if not win.winfo_exists():
                if rec_state["writer"] is not None:
                    rec_state["writer"].release()
                return
            w = canvas.winfo_width()
            h = canvas.winfo_height()
            if w < 2 or h < 2:
                win.after(50, fs_update)
                return

            frame = cam.get_frame(w, h)

            img = Image.fromarray(frame).resize((w, h))
            draw = ImageDraw.Draw(img)
            draw.text((10, 10), datetime.datetime.now().strftime("%Y-%m-%d  %H:%M:%S"),
                      fill=(0, 200, 255))
            draw.text((10, 30), cam.name, fill=(200, 220, 240))
            if rec_state["recording"]:
                draw.ellipse([w-30, 10, w-10, 30], fill=(255, 0, 0))
                draw.text((w-90, 12), "REC", fill=(255, 60, 60))

            stamped_frame = np.array(img)

            if rec_state["recording"] and rec_state["writer"] is not None:
                rw, rh = rec_state["size"]
                rec_frame = cv2.resize(frame, (rw, rh))
                bgr = cv2.cvtColor(rec_frame, cv2.COLOR_RGB2BGR)
                rec_state["writer"].write(bgr)

            img = Image.fromarray(stamped_frame)
            draw = ImageDraw.Draw(img)
            draw.text((10, 10), datetime.datetime.now().strftime("%Y-%m-%d  %H:%M:%S"),
                      fill=(0, 200, 255))
            draw.text((10, 30), cam.name, fill=(200, 220, 240))
            if rec_state["recording"]:
                draw.ellipse([w-30, 10, w-10, 30], fill=(255, 0, 0))
                draw.text((w-90, 12), "REC", fill=(255, 60, 60))

            ph[0] = ImageTk.PhotoImage(img)
            canvas.create_image(0, 0, anchor="nw", image=ph[0])
            win.after(40, fs_update)

        def on_close():
            if rec_state["writer"] is not None:
                rec_state["writer"].release()
            win.destroy()

        canvas.bind("<Double-Button-1>", lambda e: on_close())
        win.protocol("WM_DELETE_WINDOW", on_close)
        win.after(50, fs_update)

    # ══════════════════════════════════════════
    #  CONTROLS
    # ══════════════════════════════════════════
    def _reconnect_all(self):
        for cam in self.cameras:
            cam.connect()
        self._log("Connect ALL: connecting every channel",
                  event_type="RECONNECT")
        self._refresh_selected_status_label()

    def _disconnect_selected(self):
        if self.selected_ch < len(self.cameras):
            cam = self.cameras[self.selected_ch]
            cam.disconnect()
            self._log(f"Disconnected: CH{self.selected_ch+1:02d} {cam.name}",
                      event_type="DISCONNECT", device=cam.name)
            self._refresh_selected_status_label()

    def _refresh_selected_status_label(self):
        if not hasattr(self, "lbl_sel_status") or self.selected_ch >= len(self.cameras):
            return
        cam = self.cameras[self.selected_ch]
        color = {
            "Live": COLORS["green"],
            "Offline": COLORS["red"],
            "Idle": COLORS["gray"]
        }.get(cam.status, COLORS["gray"])
        self.lbl_sel_status.config(text=f"● {cam.status}", fg=color)

    def _open_file(self):
        path = filedialog.askopenfilename(
            title="Select Video File",
            filetypes=[("Video Files", "*.mp4 *.avi *.mov *.mkv *.m4v"),
                       ("All Files", "*.*")])
        if not path:
            return
        self._play_video_popup(path)

    def _play_video_popup(self, path):
        win = tk.Toplevel(self.root)
        win.title(os.path.basename(path))
        win.geometry("960x600")
        win.configure(bg="#000")

        canvas = tk.Canvas(win, bg="#000", highlightthickness=0)
        canvas.pack(fill="both", expand=True)

        lbl_loading = tk.Label(canvas, text="Loading…", bg="#000",
                               fg=COLORS["accent"], font=FONTS["body"])
        lbl_loading.place(relx=0.5, rely=0.5, anchor="center")

        ctrl = tk.Frame(win, bg=COLORS["bg_header"], height=42)
        ctrl.pack(fill="x", side="bottom")
        ctrl.pack_propagate(False)

        state = {"cap": None, "playing": True, "photo": None, "ready": False}

        def toggle_play():
            state["playing"] = not state["playing"]
            btn_play.config(text="⏸ Pause" if state["playing"] else "▶ Play")

        btn_play = tk.Button(ctrl, text="⏸ Pause", bg=COLORS["bg_card"], fg=COLORS["white"],
                             font=FONTS["body"], relief="flat", padx=14, pady=6,
                             cursor="hand2", state="disabled",
                             activebackground=COLORS["accent"], activeforeground="#000",
                             command=toggle_play)
        btn_play.pack(side="left", padx=8, pady=4)

        def on_close():
            if state["cap"] is not None:
                state["cap"].release()
            win.destroy()

        win.protocol("WM_DELETE_WINDOW", on_close)

        def _open_in_background():
            cap = cv2.VideoCapture(path)
            if not win.winfo_exists():
                cap.release()
                return
            if not cap.isOpened():
                win.after(0, lambda: [
                    messagebox.showerror(
                        "Error", f"Could not open video:\n{path}"),
                    win.destroy()
                ])
                return
            state["cap"] = cap
            state["ready"] = True
            win.after(0, lambda: [
                lbl_loading.place_forget(),
                btn_play.config(state="normal"),
                update_frame()
            ])

        threading.Thread(target=_open_in_background, daemon=True).start()

        def update_frame():
            if not win.winfo_exists() or not state["ready"]:
                return
            if state["playing"]:
                ret, frame = state["cap"].read()
                if not ret:
                    state["cap"].set(cv2.CAP_PROP_POS_FRAMES, 0)
                    ret, frame = state["cap"].read()
                if ret:
                    w = canvas.winfo_width() or 960
                    h = canvas.winfo_height() or 560
                    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                    img = Image.fromarray(rgb).resize((w, h))
                    state["photo"] = ImageTk.PhotoImage(img)
                    canvas.create_image(0, 0, anchor="nw",
                                        image=state["photo"])
            win.after(33, update_frame)

    def _zoom(self, d):
        if self.selected_ch < len(self.cameras):
            cam = self.cameras[self.selected_ch]
            cam.ptz_zoom = max(1.0, min(10.0, cam.ptz_zoom + d*0.5))

    def _refresh_all_feeds(self):
        for cam in self.cameras:
            cam.disconnect()
        for cam in self.cameras:
            cam.connect()
        self._log(f"Refresh ALL: {len(self.cameras)} channel(s) reconnecting",
                  event_type="REFRESH")
        self._refresh_selected_status_label()

    # ── Recording (sidebar / global — independent of fullscreen) ──
    def _start_cam_recording(self, cam: CameraSource):
        if cam.recording:
            return
        base = os.path.join(get_app_data_dir(), "Recordings")
        try:
            os.makedirs(base, exist_ok=True)
        except Exception:
            base = os.path.join(os.path.expanduser(
                "~"), "CameraData", "Recordings")
            os.makedirs(base, exist_ok=True)
        ts = datetime.datetime.now().strftime("%Y-%m-%d_%H.%M.%S")
        safe = "".join(c if c.isalnum() or c in (" ", "_", "-")
                       else "_" for c in cam.name).strip().replace(" ", "_")
        path = os.path.join(base, f"CH{cam.channel_id+1}_{safe}_{ts}.mp4")
        fourcc = cv2.VideoWriter_fourcc(*"mp4v")
        cam.writer = cv2.VideoWriter(path, fourcc, 15.0, (640, 480))
        cam.record_path = path
        cam.recording = True
        self._log(f"Recording: {cam.name}",
                  event_type="REC_START", device=cam.name)

    def _stop_cam_recording(self, cam: CameraSource):
        if not cam.recording:
            return
        cam.recording = False
        if cam.writer is not None:
            cam.writer.release()
            cam.writer = None
        self._log(f"Stopped: {cam.name}",
                  event_type="REC_STOP", device=cam.name)

    def _rec_selected(self):
        if self.selected_ch < len(self.cameras):
            self._start_cam_recording(self.cameras[self.selected_ch])

    def _stop_rec_selected(self):
        if self.selected_ch < len(self.cameras):
            self._stop_cam_recording(self.cameras[self.selected_ch])

    def _rec_all(self):
        for cam in self.cameras:
            self._start_cam_recording(cam)

    def _stop_all_rec(self):
        for cam in self.cameras:
            self._stop_cam_recording(cam)

