    def _repaint_widget_tree(self, widget):
        old_theme = DARK_THEME if self.theme == "light" else LIGHT_THEME
        new_theme = LIGHT_THEME if self.theme == "light" else DARK_THEME

        role_by_old_value = {v: k for k, v in old_theme.items()}

        for child in widget.winfo_children():
            if child in self._theme_protected_widgets:
                self._repaint_widget_tree(child)
                continue

            try:
                cur_bg = child.cget("bg")
            except tk.TclError:
                cur_bg = None
            try:
                cur_fg = child.cget("fg")
            except tk.TclError:
                cur_fg = None

            if cur_bg in role_by_old_value:
                child.config(bg=new_theme[role_by_old_value[cur_bg]])
            if cur_fg in role_by_old_value:
                child.config(fg=new_theme[role_by_old_value[cur_fg]])

            self._repaint_widget_tree(child)

    def _apply_ttk_theme(self):
        style = ttk.Style()
        style.configure("VMS.Treeview",
                        background=COLORS["bg_card"],
                        fieldbackground=COLORS["bg_card"],
                        foreground=COLORS["white"])
        style.configure("VMS.Treeview.Heading",
                        background=COLORS["bg_header"],
                        foreground=COLORS["accent"])

    def _infer_event_type(self, msg):
        m = msg.upper()
        if "REC_START" in m or m.startswith("RECORDING"):
            return "REC_START"
        if "REC_STOP" in m or m.startswith("STOPPED"):
            return "REC_STOP"
        if "OFFLINE" in m:
            return "OFFLINE"
        if "CONNECT" in m:
            return "CONNECT"
        if "DISCONNECT" in m:
            return "DISCONNECT"
        if "SCREENSHOT" in m or "SNAPSHOT" in m:
            return "SNAPSHOT"
        if "LAYOUT" in m:
            return "LAYOUT"
        return "INFO"

    def _log(self, msg, event_type=None, device=None):
        now = datetime.datetime.now()
        ts_full = now.strftime("%Y-%m-%d %H:%M:%S")
        ts_short = now.strftime("%H:%M:%S")
        etype = event_type or self._infer_event_type(msg)
        dev = device or "-"

        self.events.append({"ts": ts_full, "type": etype,
                           "device": dev, "message": msg})

        if hasattr(self, "event_box"):
            line = f"[{ts_short}] {msg}\n"
            self.event_box.config(state="normal")
            self.event_box.insert("end", line)
            self.event_box.see("end")
            lines = self.event_box.get("1.0", "end").split("\n")
            if len(lines) > 52:
                self.event_box.delete("1.0", f"{len(lines)-50}.0")
            self.event_box.config(state="disabled")

        if hasattr(self, "event_tree"):
            self.event_tree.insert(
                "", "end", values=(ts_full, etype, dev, msg))

        if hasattr(self, "lbl_status_bar"):
            self.lbl_status_bar.config(text=msg)

    def _make_accordion_section(self, parent, key, title, expanded=True):
        section_frame = tk.Frame(parent, bg=COLORS["bg_panel"])
        section_frame.pack(fill="x")

        header = tk.Frame(section_frame, bg=COLORS["bg_card"], cursor="hand2")
        header.pack(fill="x", pady=(4, 0))

        arrow_lbl = tk.Label(header, text="▾" if expanded else "▸",
                             bg=COLORS["bg_card"], fg=COLORS["accent"],
                             font=FONTS["small"], width=2)
        arrow_lbl.pack(side="left", padx=(8, 2), pady=6)

        title_lbl = tk.Label(header, text=title, bg=COLORS["bg_card"],
                             fg=COLORS["white"], font=FONTS["small"], anchor="w")
        title_lbl.pack(side="left", fill="x", expand=True, pady=6)

        body = tk.Frame(section_frame, bg=COLORS["bg_panel"])
        if expanded:
            body.pack(fill="x")

        self._accordion_sections[key] = {
            "body": body, "arrow": arrow_lbl, "expanded": expanded
        }

        def _toggle(e=None):
            state = self._accordion_sections[key]
            state["expanded"] = not state["expanded"]
            if state["expanded"]:
                state["body"].pack(fill="x")
                state["arrow"].config(text="▾")
            else:
                state["body"].pack_forget()
                state["arrow"].config(text="▸")
            self.root.after(10, lambda: self._sb_canvas.configure(
                scrollregion=self._sb_canvas.bbox("all")))

        header.bind("<Button-1>", _toggle)
        arrow_lbl.bind("<Button-1>", _toggle)
        title_lbl.bind("<Button-1>", _toggle)

        return body


