def show_splash(root):
    splash = tk.Toplevel(root)
    splash.overrideredirect(True)
    splash.geometry("500x300+550+350")
    splash.configure(bg=COLORS["bg_dark"])
    tk.Frame(splash, bg=COLORS["accent"], height=3).pack(fill="x")

    try:
        image = Image.open(io.BytesIO(LOGO_DARK_BYTES))
        image = image.convert("RGBA")

        width = 300
        height = int(image.height * width / image.width)

        image = image.resize((width, height), Image.LANCZOS)

        logo = ImageTk.PhotoImage(image)

        lbl = tk.Label(
            splash,
            image=logo,
            bg=COLORS["bg_dark"],
            bd=0
        )

        lbl.image = logo
        lbl.pack(pady=(20, 10))

    except Exception as e:
        print(e)

    tk.Label(splash, text="Camlytix® VMS - Video Management Software 1.0",
             bg=COLORS["bg_dark"], fg=COLORS["white"],
             font=("Segoe UI", 14)).pack()
    tk.Frame(splash, bg=COLORS["border"], height=1).pack(
        fill="x", padx=40, pady=14)
    tk.Label(splash, text="Do365 Technologies Pvt Ltd  |  Call for support: +919092222016",
             bg=COLORS["bg_dark"], fg=COLORS["bg_subheader"],
             font=("Segoe UI", 10)).pack()

    prog = ttk.Progressbar(splash, mode="determinate", length=300)
    prog.pack(pady=2)
    lbl_l = tk.Label(splash, text="Initializing…",
                     bg=COLORS["bg_dark"], fg=COLORS["gray_light"],
                     font=("Courier New", 9))
    lbl_l.pack()
    steps = ["Loading modules…", "Initializing channels…",
             "Connecting feeds…", "Starting VMS…"]

    # # 🔽 Start pinging all device IPs in the background as soon as the
    # # splash appears — runs in parallel with the progress animation.
    # threading.Thread(target=_ping_all_devices_in_background,
    #                  daemon=True).start()

    def animate(i=0):
        if not splash.winfo_exists():
            return
        if i <= 100:
            prog["value"] = i
            if i < len(steps) * 26:
                lbl_l.config(text=steps[i // 26])
            splash.after(60, lambda: animate(i + 1))
        else:
            splash.destroy()

    animate()
    return splash


