def launch_vms():
    """Login success ஆனா தான் இது call ஆகும்."""
    root = tk.Tk()
    root.withdraw()

    try:
        icon = Image.open(io.BytesIO(LOGO_DARK_BYTES)).convert("RGBA")
        icon_tk = ImageTk.PhotoImage(icon)
        root.iconphoto(True, icon_tk)
        root._icon_ref = icon_tk
    except Exception:
        pass

    style = ttk.Style()
    style.theme_use("clam")
    style.configure("TProgressbar",
                    troughcolor=COLORS["bg_card"],
                    background=COLORS["accent"],
                    lightcolor=COLORS["accent"],
                    darkcolor=COLORS["accent2"],
                    thickness=12)

    style.configure("VMS.Treeview",
                    background=COLORS["bg_card"],
                    fieldbackground=COLORS["bg_card"],
                    foreground=COLORS["white"],
                    rowheight=26,
                    font=FONTS["body"],
                    borderwidth=0)
    style.configure("VMS.Treeview.Heading",
                    background=COLORS["bg_header"],
                    foreground=COLORS["accent"],
                    font=FONTS["label"],
                    relief="flat")
    style.map("VMS.Treeview",
              background=[("selected", COLORS["accent_dim"])],
              foreground=[("selected", COLORS["white"])])

    show_splash(root)
    root.after(6500, lambda: [root.deiconify(),
               VMSApp(root), root.state("zoomed")])
    root.mainloop()


def main():
    init_db()
    run_startup_license_check()

    # Login/Register window முதல்ல தெரியும். username+password+MAC
    # match ஆகி, active_user_list.status == 'Active' ஆ இருந்தா தான்
    # launch_vms() call ஆகி VMS main window திறக்கும்.
    show_login_window(on_success=launch_vms)


if __name__ == "__main__":
    main()